<?php
$pageTitle = 'Skills';
require_once 'includes/header.php';
if ($db && $_SERVER['REQUEST_METHOD'] === 'POST') {
    check_csrf();
    try {
        $action = $_POST['form_action'] ?? '';
        if ($action === 'delete') { $stmt = $db->prepare('DELETE FROM skills WHERE id = ?'); $stmt->execute([(int) $_POST['id']]); admin_redirect('skills.php', 'Skill deleted.'); }
        if ($action === 'delete_category') { $stmt = $db->prepare('DELETE FROM skill_categories WHERE id = ?'); $stmt->execute([(int) $_POST['id']]); admin_redirect('skills.php', 'Category deleted.'); }
        if ($action === 'category') { $stmt = $db->prepare('INSERT INTO skill_categories (name, sort_order) VALUES (?, ?)'); $stmt->execute([trim($_POST['category_name']), (int) $_POST['category_sort']]); admin_redirect('skills.php', 'Category added.'); }
        if ($action === 'skill') {
            $id = (int) ($_POST['id'] ?? 0); $values = [(int) $_POST['category_id'], trim($_POST['name']), trim($_POST['icon_reference']), (int) $_POST['sort_order']];
            if ($id) { $values[] = $id; $stmt = $db->prepare('UPDATE skills SET category_id=?, name=?, icon_reference=?, sort_order=? WHERE id=?'); } else { $stmt = $db->prepare('INSERT INTO skills (category_id, name, icon_reference, sort_order) VALUES (?, ?, ?, ?)'); }
            $stmt->execute($values); admin_redirect('skills.php', $id ? 'Skill updated.' : 'Skill added.');
        }
    } catch (Throwable $exception) { $formError = $exception->getMessage(); }
}
$editId = (int) ($_GET['edit'] ?? 0); $editSkill = null;
if ($editId && $db) { $stmt = $db->prepare('SELECT * FROM skills WHERE id = ?'); $stmt->execute([$editId]); $editSkill = $stmt->fetch(); }
$categories = $db ? $db->query('SELECT * FROM skill_categories ORDER BY sort_order ASC, name ASC')->fetchAll() : [];
$skills = $db ? $db->query('SELECT s.*, c.name AS category_name FROM skills s JOIN skill_categories c ON c.id = s.category_id ORDER BY c.sort_order ASC, s.sort_order ASC, s.name ASC')->fetchAll() : [];
?>
<div class="admin-heading"><div><h1>Skills</h1><p>Organize the technologies shown on the public portfolio.</p></div></div>
<?php if (!empty($formError)): ?><div class="admin-alert admin-alert--error"><?= admin_escape($formError) ?></div><?php endif; ?>
<div class="admin-grid admin-grid--two">
<section class="admin-card"><div class="admin-card__header"><h2><?= $editSkill ? 'Edit skill' : 'Add skill' ?></h2></div><form class="admin-form" method="post"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="skill"><input type="hidden" name="id" value="<?= (int) ($editSkill['id'] ?? 0) ?>"><div><label class="form-label" for="name">Name</label><input class="form-control" id="name" name="name" required value="<?= admin_escape($editSkill['name'] ?? '') ?>"></div><div><label class="form-label" for="category_id">Category</label><select class="form-select" id="category_id" name="category_id" required><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (int) ($editSkill['category_id'] ?? 0) === (int) $category['id'] ? 'selected' : '' ?>><?= admin_escape($category['name']) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="icon_reference">Technology logo</label><input class="form-control" id="icon_reference" name="icon_reference" placeholder="simple-icons name, e.g. php" value="<?= admin_escape($editSkill['icon_reference'] ?? '') ?>"></div><div><label class="form-label" for="sort_order">Sort order</label><input class="form-control" id="sort_order" name="sort_order" type="number" value="<?= (int) ($editSkill['sort_order'] ?? 0) ?>"></div><div class="admin-form__actions"><a href="skills.php" class="btn btn-secondary">Cancel</a><button class="btn btn-primary" type="submit">Save skill</button></div></form></section>
<section class="admin-card"><div class="admin-card__header"><h2>Add category</h2></div><form class="admin-form" method="post"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="category"><div><label class="form-label" for="category_name">Category name</label><input class="form-control" id="category_name" name="category_name" required></div><div><label class="form-label" for="category_sort">Sort order</label><input class="form-control" id="category_sort" name="category_sort" type="number" value="0"></div><div class="admin-form__actions"><button class="btn btn-secondary" type="submit">Add category</button></div></form><div class="admin-sort-list" style="margin-top:var(--space-6)"><?php foreach ($categories as $category): ?><div class="admin-sort-row"><span class="admin-sort-row__label"><?= admin_escape($category['name']) ?></span><span class="text-meta text-muted">#<?= (int) $category['sort_order'] ?></span><form method="post" onsubmit="return confirm('Delete this category and its skills?');"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="delete_category"><input type="hidden" name="id" value="<?= (int) $category['id'] ?>"><button class="admin-icon-button" type="submit" aria-label="Delete category"><i data-lucide="trash-2" aria-hidden="true"></i></button></form></div><?php endforeach; ?></div></section>
</div>
<section class="admin-card" style="margin-top:var(--space-6)"><div class="admin-card__header"><h2>All skills</h2></div><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>Skill</th><th>Category</th><th>Logo</th><th>Order</th><th></th></tr></thead><tbody><?php foreach ($skills as $skill): ?><tr><td class="admin-table__title"><?= admin_escape($skill['name']) ?></td><td><?= admin_escape($skill['category_name']) ?></td><td class="text-meta"><?= admin_escape($skill['icon_reference']) ?></td><td><?= (int) $skill['sort_order'] ?></td><td><div class="admin-row-actions"><a class="admin-icon-button" href="skills.php?edit=<?= (int) $skill['id'] ?>" aria-label="Edit skill"><i data-lucide="pencil" aria-hidden="true"></i></a><form method="post"><?= admin_csrf_field() ?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?= (int) $skill['id'] ?>"><button class="admin-icon-button" type="submit" aria-label="Delete skill"><i data-lucide="trash-2" aria-hidden="true"></i></button></form></div></td></tr><?php endforeach; ?><?php if (!$skills): ?><tr><td colspan="5" class="admin-empty">No skills yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require_once 'includes/footer.php';
